#!/usr/bin/env python3
"""
Process HWPX template: fill placeholders, compute month spans, normalize budget, remove lineSegArray.
"""

import json
import re
import zipfile
import xml.etree.ElementTree as ET
from datetime import datetime
import os

# Paths
JSON_PATH = '/root/project_proposal.json'
TEMPLATE_PATH = '/root/project_proposal_template.hwpx'
OUTPUT_PATH = '/root/project_proposal_ready.hwpx'
TEMP_DIR = '/tmp/hwpx_work'

def load_json_data(path):
    """Load replacement values from JSON."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str):
    """Parse date string like '2026-08' or '2026-08-01' to (year, month)."""
    # Handle formats like "2026-08" or "2026-08-01"
    parts = date_str.strip().split('-')
    year = int(parts[0])
    month = int(parts[1])
    return (year, month)

def compute_month_span(start_str, end_str):
    """Compute month difference between two date strings."""
    start_year, start_month = parse_date(start_str)
    end_year, end_month = parse_date(end_str)
    return (end_year - start_year) * 12 + (end_month - start_month) + 1

def normalize_budget(value):
    """Remove commas from budget but keep currency symbol."""
    # Find currency symbol and number parts
    match = re.match(r'(^[^\d]*)([\d,]+)(.*)$', value)
    if match:
        prefix = match.group(1)  # Currency symbol like ₩
        number = match.group(2).replace(',', '')  # Remove commas
        suffix = match.group(3)
        return f"{prefix}{number}{suffix}"
    return value

def extract_dates_from_phase(phase_text):
    """Extract start and end dates from phase text like '... (2026-08 ~ 2026-10)'."""
    # Look for pattern like "2026-08 ~ 2026-10" or "2026-08-01 ~ 2026-10-31"
    match = re.search(r'(\d{4}-\d{2}(?:-\d{2})?)\s*~\s*(\d{4}-\d{2}(?:-\d{2})?)', phase_text)
    if match:
        return match.group(1), match.group(2)
    return None, None

def replace_placeholders(text, data):
    """Replace {{key}} placeholders in text with values from data."""
    if text is None:
        return None

    def replacer(match):
        key = match.group(1)
        if key in data:
            value = data[key]
            # Normalize budget values (remove commas, keep currency)
            if '예산' in key or ('₩' in str(value) and ',' in str(value)):
                return normalize_budget(str(value))
            return str(value)
        return match.group(0)  # Keep original if key not found

    return re.sub(r'\{\{([^}]+)\}\}', replacer, text)

def process_phase_line(text):
    """Process phase lines to add month span."""
    if text is None:
        return None

    # Check if this is a phase line (1단계, 2단계, 3단계)
    phase_match = re.match(r'^(\d단계:\s*)(.+)$', text)
    if phase_match:
        prefix = phase_match.group(1)
        content = phase_match.group(2)

        # Extract dates from the content
        start_date, end_date = extract_dates_from_phase(content)
        if start_date and end_date:
            try:
                months = compute_month_span(start_date, end_date)
                # Check if month span already exists
                if f'({months}개월)' not in text and '개월)' not in text:
                    return f"{prefix}{content} ({months}개월)"
            except Exception as e:
                print(f"Error computing month span for '{text}': {e}")

    return text

def register_namespaces():
    """Register HWPX namespaces to preserve prefixes in output."""
    namespaces = {
        'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML',
    }
    for prefix, uri in namespaces.items():
        ET.register_namespace(prefix, uri)
    return namespaces

def process_xml_content(xml_content, data):
    """Process XML content: replace placeholders, add month spans, remove lineSegArray."""
    # Register namespaces
    namespaces = register_namespaces()
    nsmap = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

    # Parse XML
    root = ET.fromstring(xml_content)

    # Track modified paragraphs
    modified_paras = set()

    # Find all text elements and process them
    for elem in root.iter():
        # Process text content
        if elem.text:
            original_text = elem.text
            new_text = replace_placeholders(original_text, data)
            new_text = process_phase_line(new_text)
            if new_text != original_text:
                elem.text = new_text
                # Mark parent paragraph as modified
                parent = elem
                while parent is not None:
                    if parent.tag == f"{{{nsmap['hp']}}}p":
                        modified_paras.add(id(parent))
                        break
                    parent = parent.find('..') if hasattr(parent, 'find') else None

        # Process tail content
        if elem.tail:
            original_tail = elem.tail
            new_tail = replace_placeholders(original_tail, data)
            new_tail = process_phase_line(new_tail)
            if new_tail != original_tail:
                elem.tail = new_tail

    # Remove lineSegArray from modified paragraphs
    for para in root.iter(f"{{{nsmap['hp']}}}p"):
        if id(para) in modified_paras:
            for child in list(para):
                if child.tag == f"{{{nsmap['hp']}}}lineSegArray" or \
                   child.tag.endswith('lineSegArray') or \
                   child.tag == 'lineSegArray' or \
                   (isinstance(child.tag, str) and 'linesegarray' in child.tag.lower()):
                    para.remove(child)

    # Convert back to string
    return ET.tostring(root, encoding='utf-8', xml_declaration=True).decode('utf-8')

def extract_hwpx(hwpx_path, extract_dir):
    """Extract HWPX file to directory."""
    os.makedirs(extract_dir, exist_ok=True)
    with zipfile.ZipFile(hwpx_path, 'r') as z:
        z.extractall(extract_dir)
        return z.namelist()

def create_hwpx(source_dir, output_path, original_entries):
    """Create HWPX file from directory contents."""
    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        # First, add mimetype without compression if it exists
        mimetype_path = os.path.join(source_dir, 'mimetype')
        if os.path.exists(mimetype_path):
            zf.write(mimetype_path, 'mimetype', zipfile.ZIP_STORED)

        # Add all other files
        for root, dirs, files in os.walk(source_dir):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, source_dir)
                if arcname != 'mimetype':  # Skip mimetype, already added
                    zf.write(file_path, arcname, zipfile.ZIP_DEFLATED)

def main():
    print("Loading JSON data...")
    data = load_json_data(JSON_PATH)
    print(f"Loaded data: {list(data.keys())}")

    print("\nExtracting HWPX template...")
    entries = extract_hwpx(TEMPLATE_PATH, TEMP_DIR)
    print(f"Extracted {len(entries)} entries")

    print("\nProcessing XML files...")
    for root, dirs, files in os.walk(TEMP_DIR):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                rel_path = os.path.relpath(file_path, TEMP_DIR)
                print(f"Processing {rel_path}...")

                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()

                processed = process_xml_content(content, data)

                with open(file_path, 'w', encoding='utf-8') as f:
                    f.write(processed)

    print("\nCreating output HWPX...")
    create_hwpx(TEMP_DIR, OUTPUT_PATH, entries)
    print(f"Created: {OUTPUT_PATH}")

    print("\nDone!")

if __name__ == '__main__':
    main()

