def extract_dates_from_phase(phase_text):
    """Extract start and end dates from phase text like '... (2026-08 ~ 2026-10)' or '... (2027-01)'."""
    # First, look for date range pattern like "2026-08 ~ 2026-10" or "2026-08-01 ~ 2026-10-31"
    match = re.search(r'(\d{4}-\d{2}(?:-\d{2})?)\s*~\s*(\d{4}-\d{2}(?:-\d{2})?)', phase_text)
    if match:
        return match.group(1), match.group(2)

    # If no range, look for single date like "(2027-01)"
    match = re.search(r'\((\d{4}-\d{2}(?:-\d{2})?)\)', phase_text)
    if match:
        # Single date means 1 month span
        date = match.group(1)
        return date, date

    return None, None

